import {sensors,crop} from './physics.mjs';
export const lessons=[
 {id:'aperture',n:'01',title:'Blende und Schärfentiefe',topic:'Schärfentiefe',intro:'Der Hintergrund soll deutlicher erkennbar werden. Die Person bleibt fokussiert und die Belichtung ausgeglichen.',setup:{focal:85,aperture:2,mode:'A',focus:5},solution:{aperture:11,mode:'A',focus:5},steps:['Blende bis mindestens ƒ/11 schließen.','Schärfebereich und Unschärfekreise vergleichen.'],answer:'Eine kleinere Öffnung begrenzt den Strahlenkegel. Die Unschärfekreise werden kleiner. Im Modus A gleicht eine längere Belichtungszeit den Lichtverlust aus.',goal:'Blende ≥ ƒ/11; Person fokussiert; Belichtung ausgeglichen.',check:(s,m)=>s.aperture>=11&&Math.abs(s.focus-s.subject-s.cameraBack)<.2&&Math.abs(m.offset)<.3},
 {id:'motion',n:'02',title:'Belichtungszeit und Bewegung',topic:'Bewegung',intro:'Die gehende Person ist verwischt. Begrenzen Sie die Bewegungsspur und gleichen Sie die Belichtung aus.',setup:{aperture:5.6,time:1/30,iso:100,ev:10,speed:4,motion:true},solution:{time:1/1000,aperture:2,iso:400},steps:['Belichtungszeit auf höchstens 1/1000 s verkürzen.','Lichtverlust mit Blende oder ISO ausgleichen.'],answer:'Die kürzere Belichtungszeit verkürzt die Strecke während der Aufnahme. Ein Stativ reduziert nur Kamerabewegung. Eine mögliche Lösung ist ƒ/2, 1/1000 s und ISO 400.',goal:'Belichtungszeit ≤ 1/1000 s; Tempo ≥ 3 m/s; |EV| < 0,4.',check:(s,m)=>s.time<=1/1000&&s.speed>=3&&Math.abs(m.offset)<.4},
 {id:'crop',n:'03',title:'Sensorformat und Bildwinkel',topic:'Sensorformat',intro:'Ein kleinerer Sensor zeigt bei gleicher Brennweite einen engeren Ausschnitt. Stellen Sie mit APS-C den ursprünglichen Bildwinkel wieder her.',setup:{focal:50,mode:'A',matchFrame:false},solution:{sensor:'apsc',focal:50*23.5/36,matchFrame:false},steps:['Ausschnitt mit Vollformat und 50 mm vergleichen.','APS-C wählen und Brennweite auf etwa 33 mm verkürzen.'],answer:'Der Sensor ändert die Brennweite nicht. Er zeichnet einen kleineren Bereich des Bildkreises auf. Für denselben horizontalen Bildwinkel gilt hier f₂ = f₁ × Sensorbreite₂ / Sensorbreite₁.',goal:'APS-C einstellen; mit etwa 33 mm den ursprünglichen Bildwinkel von 39,6° wiederherstellen.',check:(s,m)=>s.sensor==='apsc'&&Math.abs(m.fov-39.598)<2},
 {id:'perspective',n:'04',title:'Brennweite und Perspektive',topic:'Perspektive',intro:'Verändern Sie das Größenverhältnis von Person und Hintergrund, während die Person ungefähr gleich groß im Bild bleibt.',setup:{focal:35,mode:'A',autoFocus:true},solution:{cameraBack:5,focal:70,autoFocus:true},steps:['Kamera im Raumplan um mindestens 4 m zurückziehen.','Mit längerer Brennweite die ursprüngliche Größe der Person annähern.'],answer:'Der veränderte Standpunkt ändert die Perspektive. Die längere Brennweite gleicht den kleineren Abbildungsmaßstab der Person aus. Zoomen vom gleichen Standpunkt allein ändert die Perspektive nicht.',goal:'Kamera ≥ 4 m zurück; Person ähnlich groß wie mit 35 mm bei 5 m.',check:s=>s.cameraBack>=4&&Math.abs((s.focal/sensors[s.sensor].h/(s.subject+s.cameraBack))/(35/24/5)-1)<.1},
 {id:'iso',n:'05',title:'ISO und Bildrauschen',topic:'Rauschen',intro:'Verringern Sie die gesammelte Lichtmenge und erhalten Sie ungefähr dieselbe Bildhelligkeit. Vergleichen Sie die Körnung mit dem Ausgangsbild.',setup:{aperture:4,time:1/60,iso:100,ev:10},solution:{time:1/2000,iso:3200},steps:['ISO auf 3200 erhöhen.','Belichtungszeit auf etwa 1/2000 s verkürzen.'],answer:'ISO sammelt kein zusätzliches Licht. Bei kürzerer Belichtungszeit stehen weniger Photonen zur Verfügung. Die höhere Verstärkung gleicht die Helligkeit an; das Signal-Rausch-Verhältnis verschlechtert sich.',goal:'ISO ≥ 3200; Belichtungszeit ≤ 1/1000 s; |EV| < 0,4.',check:(s,m)=>s.iso>=3200&&s.time<=1/1000&&Math.abs(m.offset)<.4},
 {id:'focus',n:'06',title:'Fokus und Unschärfekreis',topic:'Fokussierung',intro:'Die Person liegt außerhalb des Fokusbereichs. Fokussieren Sie auf die Person und vergleichen Sie das normale mit dem strengen Schärfekriterium.',setup:{focal:85,aperture:1.4,focus:2.8,mode:'A',rayTargets:'person,plant,background'},solution:{focus:5,cocMode:'pixel'},steps:['Person im Raumplan doppelt anklicken.','Unter „Bild & Sensor“ den Maßstab „Fein prüfen · 2 Sensorpixel“ wählen.'],answer:'Fokussieren verändert die Abbildung auf der Sensorebene. Das strengere Schärfekriterium ändert die akzeptierte Kreisgröße, nicht die Optik. Unscharf wird das Bild stetig, nicht schlagartig an einer Bereichsgrenze.',goal:'Person fokussieren. Unter „Bild & Sensor“ → „Schärfemaßstab“ auf „Fein prüfen · 2 Sensorpixel“ wechseln: Der akzeptierte Schärfebereich wird kleiner.',check:s=>Math.abs(s.focus-s.subject-s.cameraBack)<.2&&s.cocMode==='pixel'},
 {id:'phone',n:'07',title:'Smartphone und Porträteffekt',topic:'Computational Photography',intro:'Die kurze Brennweite erzeugt viel optische Schärfentiefe. Erzeugen Sie zusätzlich Hintergrundunschärfe durch den Porträteffekt.',setup:{sensor:'phone',focal:6.8,focus:3,subject:3,foreground:1.5,background:10,mode:'A',portrait:false},solution:{portrait:true},steps:['Optisches Bild als Foto speichern.','Unter „Bild & Sensor“ den Porträteffekt aktivieren.'],answer:'Die Software ergänzt eine Tiefenmaske. Die berechneten optischen Unschärfekreise und die Schärfentiefe ändern sich dadurch nicht.',goal:'Smartphone; Porträteffekt aktiv.',check:s=>s.sensor==='phone'&&s.portrait},
 {id:'color',n:'08',title:'Weißabgleich und ND-Filter',topic:'Lichtfarbe und Lichtmenge',intro:'Die Szene wird mit warmem Kunstlicht beleuchtet. Neutralisieren Sie die Farbwiedergabe und gleichen Sie anschließend einen Graufilter aus.',setup:{scene:'studio',ev:9,temperature:3200,wb:5500,mode:'A',aperture:2.8},solution:{wb:3200,nd:3},steps:['Weißabgleich auf 3200 K setzen.','ND-Filter auf 3 EV stellen und Belichtungszeit vergleichen.'],answer:'Der Weißabgleich passt die Farbkanäle an die Lichtfarbe an. Ein idealer ND-Filter ändert nur die Lichtmenge. 3 EV entsprechen einem Faktor 8; die Zeitautomatik verlängert die Belichtungszeit entsprechend.',goal:'Weißabgleich passt zur Lichtfarbe; ND ≥ 3 EV; Belichtung ausgeglichen.',check:(s,m)=>Math.abs(s.wb-s.temperature)<200&&s.nd>=3&&Math.abs(m.offset)<.3}
];
export function learnPage(){return `<div class="content-header"><h1>Übungsaufgaben</h1><p>Die Tour erklärt die Grundlagen. Hier löst du acht eigenständige Aufgaben im freien Labor – mit Ziel, Hinweis und Lösung.</p></div><div class="lesson-grid">${lessons.map(l=>`<article class="panel lesson-card"><span class="lesson-number">${l.n}</span><h2>${l.title}</h2><canvas data-lesson-preview="${l.id}" width="480" height="320" aria-label="Ausgangsbild: ${l.title}"></canvas><p>${l.intro}</p><details><summary>Vorgehen und Erklärung</summary><ol>${l.steps.map(t=>`<li>${t}</li>`).join('')}</ol><p>${l.answer}</p></details><button data-experiment="${l.id}">Aufgabe starten ↗</button></article>`).join('')}</div>`;}
export function atlasPage(){return `<div class="content-header"><h1>Sensorformate</h1><div class="atlas-options"><label><input type="radio" name="atlas-mode" value="frame" checked> Gleicher Bildwinkel</label><label><input type="radio" name="atlas-mode" value="focal"> Gleiche Brennweite · 35 mm</label></div><p class="micro" id="atlas-method">Gleicher Standpunkt und Fokus. Zeitautomatik gleicht die Belichtung aus. Blende ƒ/4; Smartphone ƒ/1.8 fest.</p></div><div class="atlas-grid">${['medium','full','apsc','mft','inch','phone'].map(id=>{const s=sensors[id];return `<article class="panel atlas-card"><h2>${s.name}</h2><div class="sensor-illustration"><div class="sensor-chip" style="width:${s.w*3.1}px;height:${s.h*3.1}px"></div><span>${s.w} × ${s.h} mm</span></div><canvas data-atlas-preview="${id}" width="480" height="${Math.round(480*s.h/s.w)}" aria-label="Beispielaufnahme mit ${s.name}"></canvas><p data-atlas-caption="${id}" class="micro"></p><dl><dt>Seitenverhältnis</dt><dd>${(s.w/s.h).toFixed(2)} : 1</dd><dt>Crop · diagonal</dt><dd>${crop(s).toFixed(2)}×</dd><dt>Auflösung</dt><dd>${s.mp} MP</dd></dl><button data-camera="${id}">Beispiel im Labor öffnen ↗</button></article>`;}).join('')}</div>`;}
export function aboutPage(){return `<div class="content-header"><h1>Optik und Aufnahme</h1></div><div class="article-layout"><article class="panel article"><h2>Blende, Belichtungszeit, ISO</h2><p><b>Kleine ƒ-Zahl:</b> große Öffnung, mehr Licht, meist weniger Schärfentiefe. <b>Lange Belichtungszeit:</b> mehr Licht und längere Bewegungsspuren. <b>ISO:</b> Signalverstärkung; ohne Änderung von Zeit und Blende kommen keine zusätzlichen Photonen an.</p><p>Die Auto-Knöpfe zeigen, welche Einstellung nachgeführt wird. „Automatik ein“ aktiviert Belichtung, Autofokus und Weißabgleich. „Automatik aus“ übernimmt die erreichten Werte als manuelle Einstellungen. Automatikgrenzen bleiben sichtbar.</p></article><article class="panel article"><h2>Warum ist etwas unscharf?</h2><p>Nur die fokussierte Entfernung wird genau auf dem Sensor abgebildet. Davor und dahinter entstehen Unschärfekreise. Die vergrößerte Fokuslage zeigt die Schnittpunkte vor, auf oder hinter der Sensorlinie. Die gestrichelten Kreise markieren das gewählte Schärfekriterium.</p><p>Die Lupe vergrößert stark. Schärfentiefe ist ein Kriterium für „ausreichend scharf“, keine harte Grenze im Raum.</p></article><article class="panel article"><h2>Kameraquerschnitt und Berechnung</h2><p>Zwei ideale Linsengruppen, eine separate Blende, ein offener Verschluss und ein Sensor. Die Lichtwege werden paraxial berechnet; Bauteilabstände sind verkürzt. Echte Objektive besitzen oft mehr Linsen. D = f/N meint die Eintrittspupille, also das durch die Frontoptik gesehene Bild der Blende.</p><p>Die numerische Schärfentiefe und Objektunschärfe verwenden eine Dünnlinsen-Näherung. Das Bild ist eine 2,5D-Szene mit vereinfachtem Bokeh, Rauschen, Weißabgleich und Stabilisierung. Die Hand wird während der Belichtungszeit um ein festes Gelenk abgetastet.</p></article><article class="panel article"><h2>Lichtquellen</h2><p>Die Straßenlaterne leuchtet breit nach unten. Der Spot beleuchtet einen gerichteten Bereich und lässt sich drehen. Ihre Beleuchtungsstärke fällt außerhalb des Nahbereichs mit dem Quadrat der Entfernung ab. Die Stärke ist als EV₁₀₀ in 1 m Entfernung angegeben. Die Automatik misst am ausgewählten Motiv. Fenster sind selbstleuchtende Bildflächen. Sie fallen bei Nacht stärker auf als bei Tageslicht; ihr Licht wird nicht auf andere Objekte übertragen.</p><p>Die Beleuchtung wird je Objektlage angenähert. Schattenwurf, Reflexionen und spektrales Mischlicht werden nicht berechnet.</p></article><article class="panel article"><h2>ISO und Ausleseverstärkung</h2><p>ISO steht hier für eine vereinfachte Signalverstärkung. Reale Kameras können analoge und digitale Verstärkung kombinieren. Dual-Native-ISO-Kameras nutzen zwei Auslese- beziehungsweise Verstärkungsbereiche. Die Blackmagic Pocket Cinema Camera 4K verwendet beispielsweise die Basiswerte 400 und 3200. Gerätespezifische Rauschkurven werden hier nicht simuliert.</p><p><a href="https://documents.blackmagicdesign.com/UserManuals/BlackmagicPocketCinemaCamera4KManual.pdf" target="_blank" rel="noopener">Blackmagic Design · Pocket Cinema Camera Handbuch</a></p></article><article class="panel article"><h2>Bild & Sensor</h2><p><b>Auflösung:</b> ändert Pixelabstand, Beugung relativ zum Pixel und das strenge Schärfekriterium. Die Vorschau bekommt dabei keine zusätzlichen Pixel. <b>ND:</b> schwächt Licht. <b>Weißabgleich:</b> gleicht die Lichtfarbe aus.</p><p><b>Stativ und Stabilisierung:</b> reduzieren Kamerabewegung, nicht die Bewegung des Motivs. <b>Porträteffekt:</b> zusätzliche künstliche Hintergrundunschärfe nur im Smartphone-Profil.</p></article><article class="panel article wide"><h2>Quellen</h2><p>Pupillenformen werden für kleine, achsnahe Lichtpunkte geometrisch abgebildet. Iris und Motivmasken verändern Form und offene Fläche. Maskenverluste beeinflussen die Belichtung; die Zeitautomatik kann sie ausgleichen. Ganze Objektlagen bleiben vereinfacht weichgezeichnet. Wellenoptik, Abbildungsfehler und Randvignettierung sind keine vollständige Simulation.</p><p>Das Verschlusslabor zeigt zwei Vorhänge mit einer beispielhaften Laufzeit von 4 ms. Die eingestellte Belichtungszeit gilt pro Sensorzeile, nicht für den gesamten Vorhangdurchlauf. Dies ist kein Messmodell einer bestimmten Kamera.</p><p><a href="https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/bokeh-for-beginners" target="_blank" rel="noopener">Nikon · Bokeh</a> · <a href="https://imaging.nikon.com/imaging/lineup/lens/glossary/" target="_blank" rel="noopener">Nikon · Lamellenform</a> · <a href="https://www.sony.co.uk/electronics/support/articles/00018997" target="_blank" rel="noopener">Sony · Verschlussvorhänge</a></p><p><a href="https://www.nikonusa.com/learn-and-explore/c/tips-and-techniques/a-basic-look-at-the-basics-of-exposure" target="_blank" rel="noopener">Nikon · Belichtung</a> · <a href="https://www.nikonusa.com/learn-and-explore/c/products-and-innovation/iso-control" target="_blank" rel="noopener">Nikon · ISO</a> · <a href="https://www.edmundoptics.com/knowledge-center/application-notes/imaging/depth-of-field-and-depth-of-focus/" target="_blank" rel="noopener">Edmund Optics · Schärfentiefe</a> · <a href="https://marclevoy.github.io/photography-applets/" target="_blank" rel="noopener">Marc Levoy · Fotografie-Applets</a> · <a href="https://research.google/blog/night-sight-seeing-in-the-dark-on-pixel-phones/" target="_blank" rel="noopener">Google Research · Photonen und Rauschen</a></p><p class="micro">Eigene Szene und Grafiken. Unabhängige Lehrsimulation. Kamera, Fotos und Mikrofon werden nicht angefordert; die Simulation läuft im Browser.</p></article></div>`;}
